//! A keep-online Minecraft client for every protocol from 1.8 (47) to 26.1
//! (775). It logs in, stays connected, relays chat, and keeps no world
//! state, so a connection costs tens of kilobytes.
//!
//! Packet layouts come from minecraft-data (`protocol.json`, generated by
//! `scripts/gen-presence-protocol.py`) and run through a small protodef
//! interpreter ([`protodef`]); the session ([`session`]) names fields and
//! the protocol's schema decides how they go on the wire.

pub mod protodef;
pub mod proxy;
pub mod session;
pub mod table;
pub mod text;

pub use session::{Auth, AuthServers, Command, End, Event, Handle, Options, Status, ping, spawn};
pub use proxy::{Proxy, ProxyKind};
pub use table::{Dialect, dialect, dialects};
